])

# Let me think differently: What if the rule is about HORIZONTAL neighbors?
# If a cell at (r,c) is 1 (background), it becomes 4 if it has TWO or more neighbors that are 4 (horizontally or vertically?)

print("Checking 1->4 conversion (background becomes object)...")

for r in range(7):
    for c in range(22):
        if demo_input[r, c] == 1 and demo_output[r, c] == 4:
            print(f"  (r={r}, c={c}): input[...]=1 but output[...]=4, neighbors of 4: ", end="")
            count = 0
            for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
                nr, nc = (r + dr) % 7, (c + dc) % 22
                if demo_output[nr, nc] == 4:
                    count += 1
            print(f" {count}")

# Wait, I should check the output's original input position (shifted up)
print("\nChecking original input position where 1 becomes 4...")

for r in range(7):
    if demo_input[r, c] == 1 and demo_output[r, c] == 4:
        print(f"  (r={r}, c={c}): input[...]=1 but output[...]=4")

# Actually I already checked this above and found it transforms the input row (r+1)%7 to output row r

print("\nPattern verification:")
# For each output cell, check if it's 4 only when shifted input was 4
for r in range(7):
    for c in range(22):
        shifted_pos = (r + 1) % 7
        if demo_input[shifted_pos, c] == 4:
            if demo_output[r, c] != 4:
                print(f"Should be 4 at ({r},{c}) but is {demo_output[r,c]} (input[{shifted_pos},{c}] = {demo_input[shifted_pos,c]})")
        elif demo_input[shifted_pos, c] == 1:
            if demo_output[r, c] == 4:
                print(f"Should be 1 at ({r},{c}) but is {demo_output[r,c]}")

# Let me count the mismatches
mismatches = []
correct_shifts = 0
for r in range(7):
    for c in range(22):
        shifted_pos = (r + 1) % 7
        expected = demo_input[shifted_pos, c]  # This should be the expected value if just shifted
        actual = demo_output[r, c]
        if expected == actual:
            correct_shifts += 1
        elif expected == 1 and actual == 1:
            pass  # background to background
        else:
            mismatches.append((r, c, expected, actual))

print(f"\nCorrect shifts (with background): {correct_shifts}")
print(f"Mismatches: {len(mismatches)}")
for m in mismatches[:10]:
    print(f"  {m}")

